// ===== الألوان: كل منتج ممكن يبقى له أكتر من صورة/لون =====
// مثال على منتج بألوان:
// { id: 30, name: "Example", price: 200, subcatId: "w-rings", isNew: true,
//   variants: [
//       { color: "Gold",   image: "images/example-gold.jpg" },
//       { color: "Silver", image: "images/example-silver.jpg" }
//   ] }
// المنتج العادي (صورة واحدة) بيفضل شغال زي ما هو بـ image.
let selectedVariant = {};

function getVariants(product) {
    if (product.variants && product.variants.length) return product.variants;
    return [{ color: "", image: product.image }];
}

function variantPickerHTML(product) {
    const variants = getVariants(product);
    if (variants.length < 2) return "";
    const sel = selectedVariant[product.id] || 0;
    const thumbs = variants.map((v, i) => `<img id="thumb-${product.id}-${i}" src="${v.image}" alt="${v.color || ""}" title="${v.color || ""}" onclick="selectVariant(${product.id}, ${i})" style="width:38px; height:38px; object-fit:cover; cursor:pointer; border:2px solid ${i === sel ? "#000" : "#ddd"}; border-radius:4px;">`).join("");
    return `<div id="color-${product.id}" style="font-size:12px; color:#888; margin:6px 0 4px;">${variants[sel].color || ""}</div><div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:8px;">${thumbs}</div>`;
}

function selectVariant(productId, index) {
    const product = products.find(p => p.id === productId);
    const variants = getVariants(product);
    selectedVariant[productId] = index;
    document.getElementById(`img-${productId}`).src = variants[index].image;
    const label = document.getElementById(`color-${productId}`);
    if (label) label.innerText = variants[index].color || "";
    variants.forEach((v, i) => {
        const t = document.getElementById(`thumb-${productId}-${i}`);
        if (t) t.style.borderColor = i === index ? "#000" : "#ddd";
    });
}


// ===== صفحة تفاصيل المنتج: عرض كبير + زوم + كل الألوان =====
(function injectProductModalStyles() {
    const style = document.createElement("style");
    style.textContent = `
    #pd-overlay{position:fixed;top:0;right:0;bottom:0;left:0;background:rgba(0,0,0,.6);z-index:9999;display:none;align-items:center;justify-content:center;padding:16px;}
    #pd-overlay.open{display:flex;}
    .pd-box{background:#fff;width:100%;max-width:1000px;max-height:94vh;border-radius:8px;display:flex;overflow:hidden;position:relative;}
    .pd-viewer{flex:1.4;background:#f4f4f4;position:relative;overflow:hidden;min-height:340px;touch-action:none;cursor:zoom-in;user-select:none;-webkit-user-select:none;}
    .pd-viewer.zoomed{cursor:grab;}
    .pd-viewer img{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:contain;transform-origin:center center;will-change:transform;-webkit-user-drag:none;pointer-events:none;}
    .pd-info{flex:1;padding:28px 24px;overflow-y:auto;display:flex;flex-direction:column;gap:12px;}
    .pd-close{position:absolute;top:10px;right:12px;z-index:5;width:36px;height:36px;border:none;border-radius:50%;background:rgba(255,255,255,.92);font-size:22px;cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.25);}
    .pd-zoom{position:absolute;bottom:12px;left:12px;display:flex;gap:6px;z-index:4;}
    .pd-zoom button{width:38px;height:38px;border:none;border-radius:50%;background:rgba(255,255,255,.95);font-size:20px;cursor:pointer;box-shadow:0 1px 4px rgba(0,0,0,.25);}
    .pd-thumbs{display:flex;gap:8px;flex-wrap:wrap;}
    .pd-thumbs img{width:56px;height:56px;object-fit:cover;border:2px solid #ddd;border-radius:4px;cursor:pointer;}
    .pd-thumbs img.active{border-color:#000;}
    .pd-hint{font-size:12px;color:#888;}
    @media (max-width:700px){
        .pd-box{flex-direction:column;max-height:96vh;overflow-y:auto;}
        .pd-viewer{flex:none;height:55vh;min-height:0;}
        .pd-info{flex:none;overflow:visible;}
    }`;
    document.head.appendChild(style);
})();

let pdState = { id: null, index: 0, scale: 1, x: 0, y: 0 };
const pdPointers = new Map();
let pdPinchStart = null;
let pdTapStart = null;
let pdLastTap = null;

function pdDist() {
    const pts = Array.from(pdPointers.values());
    return Math.hypot(pts[0].x - pts[1].x, pts[0].y - pts[1].y) || 1;
}

function ensureProductModal() {
    if (document.getElementById("pd-overlay")) return;
    const overlay = document.createElement("div");
    overlay.id = "pd-overlay";
    overlay.innerHTML = `
        <div class="pd-box">
            <button class="pd-close" onclick="closeProduct()" aria-label="Close">&times;</button>
            <div class="pd-viewer" id="pd-viewer">
                <img id="pd-img" src="" alt="">
                <div class="pd-zoom">
                    <button onclick="pdZoomBy(1/1.4)" aria-label="Zoom out">&minus;</button>
                    <button onclick="pdZoomBy(1.4)" aria-label="Zoom in">+</button>
                    <button onclick="pdResetZoom()" aria-label="Reset zoom" style="font-size:13px;">1:1</button>
                </div>
            </div>
            <div class="pd-info">
                <h3 id="pd-name" style="margin:0;"></h3>
                <div id="pd-price" style="font-size:20px;"></div>
                <div id="pd-color" style="color:#888; font-size:14px;"></div>
                <div id="pd-thumbs" class="pd-thumbs"></div>
                <button id="pd-add" class="add-to-cart-btn" onclick="pdAddToCart()">ADD TO CART</button>
                <div class="pd-hint">Scroll, double-tap or pinch to zoom, drag to move</div>
            </div>
        </div>`;
    overlay.addEventListener("click", e => { if (e.target === overlay) closeProduct(); });
    document.body.appendChild(overlay);

    const viewer = document.getElementById("pd-viewer");
    viewer.addEventListener("wheel", e => {
        e.preventDefault();
        pdZoomBy(e.deltaY < 0 ? 1.15 : 1 / 1.15, e.clientX, e.clientY);
    }, { passive: false });

    viewer.addEventListener("pointerdown", e => {
        if (e.target.closest(".pd-zoom")) return;
        try { viewer.setPointerCapture(e.pointerId); } catch (err) {}
        pdPointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (pdPointers.size === 1) pdTapStart = { x: e.clientX, y: e.clientY };
        else pdTapStart = null;
        if (pdPointers.size === 2) pdPinchStart = { dist: pdDist(), scale: pdState.scale };
    });

    viewer.addEventListener("pointermove", e => {
        if (!pdPointers.has(e.pointerId)) return;
        const prev = pdPointers.get(e.pointerId);
        pdPointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (pdPointers.size === 2 && pdPinchStart) {
            pdZoomTo(pdPinchStart.scale * pdDist() / pdPinchStart.dist);
        } else if (pdPointers.size === 1 && pdState.scale > 1) {
            pdState.x += e.clientX - prev.x;
            pdState.y += e.clientY - prev.y;
            pdApply();
        }
    });

    const endPointer = e => {
        if (!pdPointers.has(e.pointerId)) return;
        const wasSingle = pdPointers.size === 1;
        pdPointers.delete(e.pointerId);
        if (pdPointers.size < 2) pdPinchStart = null;
        if (wasSingle && pdTapStart && e.type === "pointerup" &&
            Math.hypot(e.clientX - pdTapStart.x, e.clientY - pdTapStart.y) < 8) {
            const now = Date.now();
            if (pdLastTap && now - pdLastTap.t < 320 &&
                Math.hypot(e.clientX - pdLastTap.x, e.clientY - pdLastTap.y) < 30) {
                if (pdState.scale > 1) pdResetZoom(); else pdZoomTo(2.5, e.clientX, e.clientY);
                pdLastTap = null;
            } else {
                pdLastTap = { t: now, x: e.clientX, y: e.clientY };
            }
        }
    };
    viewer.addEventListener("pointerup", endPointer);
    viewer.addEventListener("pointercancel", endPointer);
}

function pdZoomTo(newScale, cx, cy) {
    const viewer = document.getElementById("pd-viewer");
    if (!viewer) return;
    newScale = Math.min(5, Math.max(1, newScale));
    const rect = viewer.getBoundingClientRect();
    const px = (cx === undefined ? rect.left + rect.width / 2 : cx) - (rect.left + rect.width / 2);
    const py = (cy === undefined ? rect.top + rect.height / 2 : cy) - (rect.top + rect.height / 2);
    const ratio = newScale / pdState.scale;
    pdState.x = px - (px - pdState.x) * ratio;
    pdState.y = py - (py - pdState.y) * ratio;
    pdState.scale = newScale;
    pdApply();
}

function pdZoomBy(factor, cx, cy) { pdZoomTo(pdState.scale * factor, cx, cy); }

function pdResetZoom() {
    pdState.scale = 1; pdState.x = 0; pdState.y = 0;
    pdApply();
}

function pdApply() {
    const viewer = document.getElementById("pd-viewer");
    const img = document.getElementById("pd-img");
    if (!viewer || !img) return;
    if (pdState.scale <= 1) {
        pdState.scale = 1; pdState.x = 0; pdState.y = 0;
    } else {
        const rect = viewer.getBoundingClientRect();
        const maxX = rect.width * (pdState.scale - 1) / 2;
        const maxY = rect.height * (pdState.scale - 1) / 2;
        pdState.x = Math.max(-maxX, Math.min(maxX, pdState.x));
        pdState.y = Math.max(-maxY, Math.min(maxY, pdState.y));
    }
    img.style.transform = `translate(${pdState.x}px, ${pdState.y}px) scale(${pdState.scale})`;
    viewer.classList.toggle("zoomed", pdState.scale > 1);
}

function pdRender() {
    const product = products.find(p => p.id === pdState.id);
    const variants = getVariants(product);
    const v = variants[pdState.index];
    const img = document.getElementById("pd-img");
    img.src = v.image;
    img.alt = product.name;
    document.getElementById("pd-color").innerText = v.color || "";
    document.getElementById("pd-thumbs").innerHTML = variants.length < 2 ? "" :
        variants.map((x, i) => `<img class="${i === pdState.index ? "active" : ""}" src="${x.image}" alt="${x.color || ""}" title="${x.color || ""}" onclick="pdSelect(${i})">`).join("");
    pdResetZoom();
}

function pdSelect(index) {
    pdState.index = index;
    selectedVariant[pdState.id] = index;
    if (document.getElementById(`img-${pdState.id}`)) selectVariant(pdState.id, index);
    pdRender();
}

function openProduct(id) {
    ensureProductModal();
    const product = products.find(p => p.id === id);
    pdState = { id: id, index: selectedVariant[id] || 0, scale: 1, x: 0, y: 0 };
    document.getElementById("pd-name").innerText = product.name;
    document.getElementById("pd-price").innerText = product.price + " EGP";
    document.getElementById("pd-add").innerText = "ADD TO CART";
    pdRender();
    document.getElementById("pd-overlay").classList.add("open");
    document.body.style.overflow = "hidden";
}

function closeProduct() {
    const overlay = document.getElementById("pd-overlay");
    if (overlay) overlay.classList.remove("open");
    pdPointers.clear(); pdPinchStart = null;
    document.body.style.overflow = "";
}

function pdAddToCart() {
    addToCart(pdState.id);
    const btn = document.getElementById("pd-add");
    btn.innerText = "ADDED ✓";
    setTimeout(() => { btn.innerText = "ADD TO CART"; }, 1200);
}

document.addEventListener("keydown", e => {
    const overlay = document.getElementById("pd-overlay");
    if (!overlay || !overlay.classList.contains("open")) return;
    if (e.key === "Escape") closeProduct();
    const product = products.find(p => p.id === pdState.id);
    const n = getVariants(product).length;
    if (n > 1 && e.key === "ArrowRight") pdSelect((pdState.index + 1) % n);
    if (n > 1 && e.key === "ArrowLeft") pdSelect((pdState.index - 1 + n) % n);
});

let cart = [];

const heroSection = document.getElementById("hero-section");
const sectionHeading = document.getElementById("section-heading");
const subcatGrid = document.getElementById("subcategories-grid");
const productsGrid = document.getElementById("products-grid");
const breadcrumb = document.getElementById("breadcrumb");

function goHome() {
    setActiveTab("tab-home");
    heroSection.style.display = "block";
    breadcrumb.style.display = "none";
    subcatGrid.style.display = "none";
    productsGrid.style.display = "grid";
    sectionHeading.innerText = "NEW ARRIVALS";

    const newProducts = products.filter(p => p.isNew);
    renderProducts(newProducts);
}

function selectMainCategory(catKey) {
    setActiveTab(`tab-${catKey}`);
    const category = storeCategories[catKey];
    
    heroSection.style.display = "none";
    breadcrumb.style.display = "block";
    breadcrumb.innerHTML = `<span onclick="goHome()">Home</span> / ${category.title}`;
    
    sectionHeading.innerText = category.title;
    productsGrid.style.display = "none";
    subcatGrid.style.display = "grid";
    subcatGrid.innerHTML = "";

    category.subcategories.forEach(sub => {
        subcatGrid.innerHTML += `
            <div class="subcat-card" onclick="selectSubcategory('${catKey}', '${sub.id}', '${sub.name}')">
                <img src="${sub.image || 'https://images.unsplash.com/photo-1515562141207-7a88fb7ce338?auto=format&fit=crop&w=500&q=80'}" alt="${sub.name}">
                <div class="subcat-title">${sub.name}${sub.comingSoon ? '<div style="font-size:11px; letter-spacing:2px; margin-top:4px;">COMING SOON 🔥</div>' : ''}</div>
            </div>
        `;
    });
}

function selectSubcategory(catKey, subId, subName) {
    const category = storeCategories[catKey];
    
    breadcrumb.innerHTML = `<span onclick="goHome()">Home</span> / <span onclick="selectMainCategory('${catKey}')">${category.title}</span> / ${subName}`;
    sectionHeading.innerText = subName;
    
    subcatGrid.style.display = "none";
    productsGrid.style.display = "grid";

    const sub = category.subcategories.find(s => s.id === subId);
    if (sub && sub.comingSoon) {
        productsGrid.innerHTML = `<div style="grid-column: 1/-1; text-align:center; padding: 60px 0;"><div style="font-size:28px; letter-spacing:4px;">COMING SOON 🔥</div><p style="color:#888; margin-top:12px;">New pieces are on the way. Stay tuned!</p></div>`;
        return;
    }

    const filteredProducts = products.filter(p => p.subcatId === subId);
    renderProducts(filteredProducts);
}

function renderProducts(list) {
    productsGrid.innerHTML = "";
    if (list.length === 0) {
        productsGrid.innerHTML = `<p style="grid-column: 1/-1; text-align:center; color:#888; padding: 40px 0;">No items available in this section yet. Check back soon!</p>`;
        return;
    }

    list.forEach(product => {
        productsGrid.innerHTML += `
            <div class="product-card">
                <div class="main-img-container">
                    <img id="img-${product.id}" src="${getVariants(product)[selectedVariant[product.id] || 0].image}" alt="${product.name}" class="product-main-img" style="cursor:pointer;" onclick="openProduct(${product.id})">
                </div>
                <div>
                    <h4 class="product-name" style="cursor:pointer;" onclick="openProduct(${product.id})">${product.name}</h4>
                    <div class="product-price">${product.price} EGP</div>
                    ${variantPickerHTML(product)}
                    <button class="add-to-cart-btn" onclick="addToCart(${product.id})">ADD TO CART</button>
                </div>
            </div>
        `;
    });
}

function setActiveTab(tabId) {
    document.querySelectorAll(".cat-tab").forEach(btn => btn.classList.remove("active"));
    document.getElementById(tabId).classList.add("active");
}

function addToCart(id) {
    const item = products.find(p => p.id === id);
    const v = getVariants(item)[selectedVariant[id] || 0];
    cart.push({ ...item, color: v.color || "", image: v.image });
    updateCartUI();
}

function removeFromCart(index) {
    cart.splice(index, 1);
    updateCartUI();
}

function updateCartUI() {
    document.getElementById("cart-count").innerText = cart.length;
    const cartItemsContainer = document.getElementById("cart-items");
    const cartTotalEl = document.getElementById("cart-total");

    cartItemsContainer.innerHTML = "";
    let total = 0;

    cart.forEach((item, index) => {
        total += item.price;
        cartItemsContainer.innerHTML += `
            <div class="cart-item">
                <div class="cart-item-info">
                    <h4>${item.name}${item.color ? " - " + item.color : ""}</h4>
                    <span>${item.price} EGP</span>
                </div>
                <button class="remove-btn" onclick="removeFromCart(${index})">Remove</button>
            </div>
        `;
    });

    cartTotalEl.innerText = total;
}

function toggleCart() {
    document.getElementById("cart-sidebar").classList.toggle("active");
    document.getElementById("cart-overlay").classList.toggle("active");
}

function checkoutWhatsApp() {
    if (cart.length === 0) {
        alert("Your cart is empty!");
        return;
    }

    const name = document.getElementById("cust-name").value.trim();
    const phone = document.getElementById("cust-phone").value.trim();
    const address = document.getElementById("cust-address").value.trim();

    if (!name || !phone || !address) {
        alert("Please fill in all shipping details (Name, Phone, Address) before ordering.");
        return;
    }

    const phoneNumber = "201125009524";
    let message = `New Order from ATHAR Store:\n\n`;
    message += `Customer Name: ${name}\n`;
    message += `Phone Number: ${phone}\n`;
    message += `Address: ${address}\n\n`;
    message += `Items Ordered:\n`;

    let total = 0;
    cart.forEach(item => {
        message += `• ${item.name}${item.color ? " (" + item.color + ")" : ""} - ${item.price} EGP\n`;
        total += item.price;
    });

    let advance = total * 0.25;
    message += `\nTotal Amount: ${total} EGP`;
    message += `\nRequired Advance (25%): ${advance} EGP (via InstaPay/Cash to 01125009524)`;
    message += `\nRemaining Upon Delivery: ${total - advance} EGP`;

    window.open(`https://wa.me/${phoneNumber}?text=${encodeURIComponent(message)}`, "_blank");
}

goHome();